+    return Promise.reject(
+      new RuntimeError(
+        RuntimeErrorCode.EXTERNAL_RESOURCE_LOADING_FAILED,
+        ngDevMode && `Could not load resource: ${url}. Response status: ${response.status}`,
+      ),
+    );
+  }
+  return response.text();

