+import {SplitAreaDirective} from '../../../../shared/split/splitArea.directive';
+
+@Component({
+  selector: 'ng-recording-visualizer',
+  templateUrl: './recording-visualizer.component.html',
+  styleUrls: ['./recording-visualizer.component.scss'],
