+        fs.writeFile(
+          COMPONENT,
+          `
+          import {Component} from '@angular/core';
+          @Component({
+            selector: 'test-cmp',
+            templateUrl: './template.html',
+          })
+          export class Cmp {}
+        `,
+        );
+        fs.writeFile(TEMPLATE, `<h1>Resource</h1>`);
+
+        const options: NgCompilerOptions = {
+          strictTemplates: true,
+        };
