+    expect(fixture.componentInstance.b).toBe(1);
+    expect(fixture.componentInstance.c).toBe(2);
+  });
+
+  it('should support exponentiation assignment operator in templates', () => {
+    @Component({template: '<button (click)="a **= b **= c"></button>'})
+    class TestComponent {
+      a = 0.5;
+      b = 2;
+      c = 3;
