+              `[${event.element.innerText.trim()}] ${event.fromState} => ${event.toState}`,
+            );
+          }
+
+          trackItem(_index: number, item: number) {
+            return item.toString();
+          }
+          addItem() {
+            this.items.push(this.items.length);
