+    });
+
+    it('should apply the `display` and `position` styles as regular inline styles for the duration of the animation', () => {
+      @Component({
+        selector: 'ani-cmp',
+        template: `
+          <div #elm [@myAnimation]="myAnimationExp" style="display:table; position:fixed"></div>
+        `,
+        animations: [
