+      expect(elm.style.getPropertyValue('position')).toEqual('fixed');
+    });
+
+    it('should set normalized style property values on animation end', () => {
+      @Component({
+        selector: 'ani-cmp',
+        template: `
+          <div #elm [@myAnimation]="myAnimationExp" style="width: 100%; font-size: 2rem"></div>
+        `,
