+    const cat = signal({name: 'pirojok-the-cat', age: 4});
+    const f = form(
+      cat,
+      (p) => {
+        min(p.age, 4);
+      },
+      {injector: TestBed.inject(Injector)},
+    );
+
+    expect(f.age().errors()).toEqual([]);
+  });
+
+  it('returns no errors when the value is larger', () => {
+    const cat = signal({name: 'pirojok-the-cat', age: 10});
+    const f = form(
+      cat,
+      (p) => {
+        min(p.age, 5);
+      },
+      {injector: TestBed.inject(Injector)},
+    );
+
+    expect(f.age().errors()).toEqual([]);
+  });
