+            return valueOf(p.category) === 'A' ? 8 : 3;
+          });
+        },
+        {injector: TestBed.inject(Injector)},
+      );
+
+      expect(f.text().errors()).toEqual([ValidationError.minLength(8)]);
+
+      f.category().value.set('B');
+      expect(f.text().errors()).toEqual([]);
+    });
+  });
+});

