+        moduleSymbol.addRemotelyScopedComponent(symbol, symbol.usedDirectives, symbol.usedPipes);
+      }
+    } else {
+      // We are not able to handle this cycle so throw an error.
+      const relatedMessages: ts.DiagnosticRelatedInformation[] = [];
