+    new TsCreateProgramDriver(program, host, options, []),
+    /* perfRecorder */ null,
+    /*enableTemplateTypeChecker*/ true,
+    /*usePoisonedData*/ false,
+  );
+  const compiler = NgCompiler.fromTicket(ticket, host);
+  return {compiler, sourceFile: program.getSourceFile(FILE)!};
+}

