+      if (tag) {
+        const prefix = match[SelectorRegexp.PREFIX];
+        if (prefix === '#') {
+          // #hash
+          current.addAttribute('id', tag.slice(1));
+        } else if (prefix === '.') {
+          // Class
+          current.addClassName(tag.slice(1));
+        } else {
