+    if (attrs) {
+      for (let i = 0; i < attrs.length; i += 2) {
+        const name = attrs[i];
+        const value = attrs[i + 1];
+
+        const terminalValuesMap = this._attrValueMap.get(name)!;
+        if (value) {
+          result =
+            this._matchTerminal(terminalValuesMap, '', cssSelector, matchedCallback) || result;
+        }
+        result =
+          this._matchTerminal(terminalValuesMap, value, cssSelector, matchedCallback) || result;
+
+        const partialValuesMap = this._attrValuePartialMap.get(name)!;
+        if (value) {
+          result = this._matchPartial(partialValuesMap, '', cssSelector, matchedCallback) || result;
+        }
+        result =
+          this._matchPartial(partialValuesMap, value, cssSelector, matchedCallback) || result;
+      }
+    }
+    return result;
+  }
+
+  /** @internal */
+  _matchTerminal(
+    map: Map<string, SelectorContext<T>[]>,
+    name: string,
+    cssSelector: CssSelector,
+    matchedCallback: ((c: CssSelector, a: any) => void) | null,
+  ): boolean {
+    if (!map || typeof name !== 'string') {
+      return false;
+    }
+
+    let selectables: SelectorContext<T>[] = map.get(name) || [];
+    const starSelectables: SelectorContext<T>[] = map.get('*')!;
+    if (starSelectables) {
+      selectables = selectables.concat(starSelectables);
+    }
+    if (selectables.length === 0) {
+      return false;
+    }
+    let selectable: SelectorContext<T>;
+    let result = false;
+    for (let i = 0; i < selectables.length; i++) {
+      selectable = selectables[i];
+      result = selectable.finalize(cssSelector, matchedCallback) || result;
+    }
+    return result;
+  }
+
+  /** @internal */
+  _matchPartial(
+    map: Map<string, SelectorMatcher<T>>,
+    name: string,
+    cssSelector: CssSelector,
+    matchedCallback: ((c: CssSelector, a: any) => void) | null,
+  ): boolean {
+    if (!map || typeof name !== 'string') {
+      return false;
+    }
+
+    const nestedSelector = map.get(name);
+    if (!nestedSelector) {
+      return false;
+    }
+    // TODO(perf): get rid of recursion and measure again
+    // TODO(perf): don't pass the whole selector into the recursion,
+    // but only the not processed parts
+    return nestedSelector.match(cssSelector, matchedCallback);
+  }
+}
+
+export class SelectorListContext {
+  alreadyMatched: boolean = false;
+
+  constructor(public selectors: CssSelector[]) {}
+}
+
+// Store context to pass back selector and context when a selector is matched
+export class SelectorContext<T = any> {
+  notSelectors: CssSelector[];
+
+  constructor(
+    public selector: CssSelector,
+    public cbContext: T,
+    public listContext: SelectorListContext,
+  ) {
+    this.notSelectors = selector.notSelectors;
+  }
+
+  finalize(cssSelector: CssSelector, callback: ((c: CssSelector, a: T) => void) | null): boolean {
+    let result = true;
+    if (this.notSelectors.length > 0 && (!this.listContext || !this.listContext.alreadyMatched)) {
+      const notMatcher = SelectorMatcher.createNotMatcher(this.notSelectors);
+      result = !notMatcher.match(cssSelector, null);
+    }
+    if (result && callback && (!this.listContext || !this.listContext.alreadyMatched)) {
+      if (this.listContext) {
+        this.listContext.alreadyMatched = true;
+      }
+      callback(this.selector, this.cbContext);
+    }
+    return result;
+  }
+}
+
+export class SelectorlessMatcher<T = unknown> {
+  constructor(private registry: Map<string, T[]>) {}
+
+  match(name: string): T[] {
+    return this.registry.has(name) ? this.registry.get(name)! : [];
+  }
+}

