+import {
+  calculateNesting,
+  getMainBlock,
+  getOriginals,
+  getPlaceholder,
+  hasLineBreaks,
+  parseTemplate,
+  reduceNestingOffset,
+} from './util';
+
+export const ngif = '*ngIf';
+export const boundngif = '[ngIf]';
