+async function makeWorkerRequest(
+  scope: SwTestHarness,
+  url: string,
+  clientId = 'default',
+  resultingClientId = 'worker',
+  init?: Object,
+): Promise<string | null> {
+  const [resPromise, done] = scope.handleFetch(
+    new MockRequest(url, {...init, destination: 'worker'}),
+    clientId,
+    resultingClientId,
+  );
+  await done;
+  const res = await resPromise;
+  if (res !== undefined && res.ok) {
+    return res.text();
+  }
+  return null;
