+})
+class DecoratorEmitingEvent {
+  msg: string;
+  emitter;
+
+  constructor(@EventEmitter('event') emitter:Function) {
+    this.msg = '';
+    this.emitter = emitter;
+  }
+
+  fireEvent(msg: string) {
+    this.emitter(msg);
+  }
+
+  onEvent(msg: string) {
+    this.msg = msg;
+  }
+}
+
+@Decorator({
+  selector: '[listener]',
+  events: {'event': 'onEvent($event)'}
+})
+class DecoratorListeningEvent {
+  msg: string;
+
+  constructor() {
+    this.msg = '';
+  }
+
+  onEvent(msg: string) {
+    this.msg = msg;
+  }
+}
+
+@Component({
